  // The static analyzer configuration is shared across all instances and threads. Groovy scripts can be parsed on
  // any thread (both during ingestion and when validating queries on the broker), so the configuration is stored in
  // an AtomicReference to guarantee that updates are applied atomically and become visible immediately without
  // requiring a service restart. A null value means that static analysis is disabled.
  private static final AtomicReference<GroovyStaticAnalyzerConfig> GROOVY_STATIC_ANALYZER_CONFIG =
      new AtomicReference<>();

  private final List<String> _arguments;
  private final int _numArguments;
  private final Binding _binding;
  private final Script _script;
  private final String _expression;

  public GroovyFunctionEvaluator(String closure) {
    _expression = closure;
    Matcher matcher = GROOVY_FUNCTION_PATTERN.matcher(closure);
    Preconditions.checkState(matcher.matches(), "Invalid transform expression: %s", closure);
    String arguments = matcher.group(ARGUMENTS_GROUP_NAME);
    if (arguments != null) {
      _arguments = Splitter.on(ARGUMENTS_SEPARATOR).trimResults().splitToList(arguments);
    } else {
      _arguments = Collections.emptyList();
    }
    _numArguments = _arguments.size();
    _binding = new Binding();
    _script = parseGroovyScript(matcher.group(SCRIPT_GROUP_NAME), _binding);
  }

  public static String getGroovyExpressionPrefix() {
    return GROOVY_EXPRESSION_PREFIX;
  }

  /**
   * Set the global Groovy static analyzer configuration. The configuration is applied to every Groovy script which is
   * parsed after this method returns. Passing {@code null} disables static analysis. This method is thread-safe and
   * takes effect immediately without requiring a service restart.
   */
  public static void setGroovyStaticAnalyzerConfig(GroovyStaticAnalyzerConfig groovyStaticAnalyzerConfig) {
    GROOVY_STATIC_ANALYZER_CONFIG.set(groovyStaticAnalyzerConfig);
  }

  /**
   * @return The active Groovy static analyzer configuration, or {@code null} if static analysis is disabled.
   */
  public static GroovyStaticAnalyzerConfig getConfig() {
    return GROOVY_STATIC_ANALYZER_CONFIG.get();
  }

  /**
   * Parse and compile the given Groovy script, validating it against the active static analyzer configuration. If a
   * static analyzer configuration is set, scripts which violate the configured policy (disallowed imports, receivers,
   * method names, method definitions, etc.) will cause an exception to be thrown. If no configuration is set, the
   * script is parsed without any restrictions.
   *
   * @param script the Groovy script to parse
   * @return the compiled {@link Script}
   * @throws RuntimeException if the script violates the configured static analysis policy or cannot be compiled
   */
  public static Script parseGroovyScript(String script) {
    return parseGroovyScript(script, new Binding());
  }

  private static Script parseGroovyScript(String script, Binding binding) {
    GroovyStaticAnalyzerConfig config = GROOVY_STATIC_ANALYZER_CONFIG.get();
    CompilerConfiguration compilerConfiguration = new CompilerConfiguration();
    if (config != null) {
      compilerConfiguration.addCompilationCustomizers(createSecureASTCustomizer(config));
    }
    GroovyShell shell = new GroovyShell(binding, compilerConfiguration);
    return shell.parse(script);
  }

  private static SecureASTCustomizer createSecureASTCustomizer(GroovyStaticAnalyzerConfig config) {
    SecureASTCustomizer secureASTCustomizer = new SecureASTCustomizer();
    // Reject scripts which define new methods when method definitions are not allowed.
    secureASTCustomizer.setMethodDefinitionAllowed(config.isMethodDefinitionAllowed());
    // Enforce the import/receiver allow-lists. Enabling the indirect import check ensures that classes cannot be
    // referenced by their fully-qualified name to bypass the import allow-list.
    secureASTCustomizer.setIndirectImportCheckEnabled(true);
    if (config.getAllowedImports() != null) {
      secureASTCustomizer.setImportsWhitelist(config.getAllowedImports());
    }
    if (config.getAllowedStaticImports() != null) {
      secureASTCustomizer.setStaticImportsWhitelist(config.getAllowedStaticImports());
    }
    if (config.getAllowedReceivers() != null) {
      secureASTCustomizer.setReceiversWhiteList(config.getAllowedReceivers());
    }
    List<String> disallowedMethodNames = config.getDisallowedMethodNames();
    if (disallowedMethodNames != null && !disallowedMethodNames.isEmpty()) {
      secureASTCustomizer.addExpressionCheckers(new DisallowedMethodNameChecker(disallowedMethodNames));
    }
    return secureASTCustomizer;
  }

  /**
   * An {@link SecureASTCustomizer.ExpressionChecker} which rejects any method call whose name is in the configured
   * list of disallowed method names. This is used to block dangerous methods such as {@code execute} (used to run
   * shell commands) and {@code invoke} (used for reflection based attacks).
   */
  private static class DisallowedMethodNameChecker implements SecureASTCustomizer.ExpressionChecker {
    private final List<String> _disallowedMethodNames;

    DisallowedMethodNameChecker(List<String> disallowedMethodNames) {
      _disallowedMethodNames = disallowedMethodNames;
    }

    @Override
    public boolean isAuthorized(Expression expression) {
      if (expression instanceof MethodCallExpression) {
        MethodCallExpression methodCall = (MethodCallExpression) expression;
        return !_disallowedMethodNames.contains(methodCall.getMethodAsString());
      }
      return true;
    }
