   * <p>If Groovy is globally disabled (via broker or table config), any usage of a Groovy transform function in the
   * query is rejected. Otherwise, every Groovy script embedded in the query is run through the configured static
   * analyzer, which rejects scripts attempting potentially malicious operations (such as executing shell commands).
   */
  @VisibleForTesting
  static void validateGroovyScript(PinotQuery pinotQuery, boolean disableGroovy) {
    List<Expression> selectList = pinotQuery.getSelectList();
    for (Expression expression : selectList) {
      validateGroovyScript(expression, disableGroovy);
    }
    List<Expression> orderByList = pinotQuery.getOrderByList();
    if (orderByList != null) {
      for (Expression expression : orderByList) {
        // NOTE: Order-by is always a Function with the ordering of the Expression
        validateGroovyScript(expression.getFunctionCall().getOperands().get(0), disableGroovy);
      }
    }
    Expression havingExpression = pinotQuery.getHavingExpression();
    if (havingExpression != null) {
      validateGroovyScript(havingExpression, disableGroovy);
    }
    Expression filterExpression = pinotQuery.getFilterExpression();
    if (filterExpression != null) {
      validateGroovyScript(filterExpression, disableGroovy);
    }
    List<Expression> groupByList = pinotQuery.getGroupByList();
    if (groupByList != null) {
      for (Expression expression : groupByList) {
        validateGroovyScript(expression, disableGroovy);
      }
    }
  }

  private static void validateGroovyScript(Expression expression, boolean disableGroovy) {
    Function function = expression.getFunctionCall();
    if (function == null) {
      return;
    }
    if (function.getOperator().equals("groovy")) {
      if (disableGroovy) {
        throw new BadQueryRequestException("Groovy transform functions are disabled for queries");
      } else {
        groovySecureAnalysis(function);
      }
    }
    for (Expression operandExpression : function.getOperands()) {
      validateGroovyScript(operandExpression, disableGroovy);
    }
  }

  private static void groovySecureAnalysis(Function function) {
    List<Expression> operands = function.getOperands();
    if (operands.size() < 2) {
      throw new BadQueryRequestException("Groovy transform function must have at least 2 arguments in query: "
          + function);
    }
    // second argument in the groovy function is the script
    String script = operands.get(1).getLiteral().getFieldValue().toString();
    try {
      GroovyFunctionEvaluator.parseGroovyScript(script);
    } catch (Exception e) {
      throw new BadQueryRequestException("Groovy transform function validation failed: " + e.getMessage(), e);
    }
